MODEL_EXECUTION = '\n"""PIRS model execution and residual materialization boundary.\n\nSlice 17B consumes the Slice 17A design matrix artifact, fits a deterministic\nlocal residualization model, writes coefficients/fitted/residual artifacts,\nand registers the model/residual relation in the 17-key output bundle. HSIC\nremains blocked; compile and output validation semantics are not modified.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport math\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Mapping, Sequence\n\nimport numpy as np\nimport pyarrow as pa\nimport pyarrow.parquet as pq\n\n\nDEFAULT_MATRIX_MANIFEST = Path("Tables") / "pirs_design_matrix_manifest.json"\nDEFAULT_MODEL_MANIFEST = Path("Tables") / "pirs_model_execution_manifest.json"\nDEFAULT_COEFFICIENTS = Path("Tables") / "pirs_model_coefficients.parquet"\nDEFAULT_FITTED_VALUES = Path("Tables") / "pirs_fitted_values.parquet"\nDEFAULT_RESIDUAL_VALUES = Path("Tables") / "pirs_residual_values.parquet"\nMODEL_GATE_KEY = "pirs_model_execution_gate"\nJSON_ATTACH_TARGETS: tuple[str, ...] = (\n    "RunConfig.json",\n    "P_vector.json",\n    "UserIntent.json",\n    "ReproducibilityManifest.json",\n)\nRESIDUAL_WARNING = "model_derived_residual_not_raw_epidemiological_variable"\n\n\nclass PIRSModelExecutionError(RuntimeError):\n    """Raised when model execution receives malformed or blocked input."""\n\n\ndef _now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _compact(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)\n\n\ndef _load_json(path: Path) -> dict[str, Any]:\n    if not path.exists():\n        return {}\n    try:\n        payload = json.loads(path.read_text(encoding="utf-8"))\n    except json.JSONDecodeError:\n        return {}\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _write_json(path: Path, payload: Mapping[str, Any]) -> Path:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(dict(payload), ensure_ascii=False, sort_keys=True, indent=2, default=str), encoding="utf-8")\n    return path\n\n\ndef _read_rows(path: Path) -> list[dict[str, Any]]:\n    if not path.exists():\n        return []\n    return [dict(row) for row in pq.read_table(path).to_pylist()]\n\n\ndef _write_rows(path: Path, rows: Sequence[Mapping[str, Any]]) -> Path:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    pq.write_table(pa.Table.from_pylist([dict(row) for row in rows]), path)\n    return path\n\n\ndef _write_rows_like(path: Path, rows: Sequence[Mapping[str, Any]]) -> Path:\n    schema = pq.read_table(path).schema\n    shaped = [{name: row.get(name) for name in schema.names} for row in rows]\n    if shaped:\n        table = pa.Table.from_pylist(shaped, schema=schema)\n    else:\n        table = pa.Table.from_arrays([pa.array([], type=field.type) for field in schema], schema=schema)\n    pq.write_table(table, path)\n    return path\n\n\ndef _append_unique_rows_like(path: Path, rows: Sequence[Mapping[str, Any]], *, id_column: str) -> Path:\n    incoming_ids = {str(row.get(id_column)) for row in rows if row.get(id_column) not in (None, "")}\n    existing = [row for row in _read_rows(path) if str(row.get(id_column)) not in incoming_ids]\n    return _write_rows_like(path, [*existing, *[dict(row) for row in rows]])\n\n\ndef _hash_payload(payload: Mapping[str, Any]) -> str:\n    raw = json.dumps(dict(payload), ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")\n    return hashlib.sha256(raw).hexdigest()\n\n\ndef _safe_id(value: Any) -> str:\n    raw = str(value or "field").lower()\n    out = "".join(ch if ch.isalnum() else "_" for ch in raw).strip("_")\n    return out or "field"\n\n\ndef _field_specs(manifest: Mapping[str, Any]) -> list[dict[str, Any]]:\n    specs = manifest.get("field_specs")\n    return [dict(item) for item in specs] if isinstance(specs, list) else []\n\n\ndef _field_id_by_role(manifest: Mapping[str, Any], role: str) -> str | None:\n    for spec in _field_specs(manifest):\n        if spec.get("role") == role and spec.get("field_id") not in (None, ""):\n            return str(spec.get("field_id"))\n    return None\n\n\ndef _covariate_field_ids(manifest: Mapping[str, Any]) -> list[str]:\n    return [str(spec.get("field_id")) for spec in _field_specs(manifest) if spec.get("role") == "covariate" and spec.get("field_id") not in (None, "")]\n\n\ndef _matrix_path(run_dir: Path, manifest: Mapping[str, Any]) -> Path:\n    raw = manifest.get("matrix_path")\n    if raw in (None, ""):\n        return run_dir / "Tables" / "pirs_design_matrix.parquet"\n    path = Path(str(raw))\n    if path.is_absolute() or path.exists():\n        return path\n    return run_dir / path\n\n\ndef _blocking_manifest(*, run_dir: Path, model_manifest_path: Path, design_matrix_manifest_path: Path, reasons: Sequence[str]) -> dict[str, Any]:\n    payload = {\n        "schema_version": "1.0",\n        "slice": "17B",\n        "artifact": "pirs_model_execution_manifest",\n        "status": "blocked",\n        "model_fit_state": "blocked",\n        "residual_state": "not_created",\n        "hsic_state": "blocked",\n        "run_dir": str(run_dir),\n        "manifest_path": str(model_manifest_path),\n        "source_design_matrix_manifest": str(design_matrix_manifest_path),\n        "model_id": None,\n        "residual_field_id": None,\n        "row_count": 0,\n        "coefficient_count": 0,\n        "blocking_reasons": list(dict.fromkeys(str(reason) for reason in reasons)),\n        "mutated_output_bundle": False,\n    }\n    _write_json(model_manifest_path, payload)\n    return payload\n\n\ndef _design_columns(manifest: Mapping[str, Any], rows: Sequence[Mapping[str, Any]]) -> tuple[str, list[str], str | None]:\n    if not rows:\n        return "response", [], None\n    columns = set(rows[0].keys())\n    response = "response" if "response" in columns else "outcome"\n    covariates = [spec.get("column") for spec in _field_specs(manifest) if spec.get("role") == "covariate"]\n    covariates = [str(col) for col in covariates if col in columns]\n    if not covariates:\n        covariates = sorted(col for col in columns if str(col).startswith("covariate_"))\n    offset = next((str(spec.get("column")) for spec in _field_specs(manifest) if spec.get("role") == "offset" and spec.get("column") in columns), None)\n    if offset is None and "offset" in columns:\n        offset = "offset"\n    return response, covariates, offset\n\n\ndef _fit_least_squares(*, rows: Sequence[Mapping[str, Any]], response_column: str, covariate_columns: Sequence[str], offset_column: str | None, family: str) -> dict[str, Any]:\n    y = np.asarray([float(row[response_column]) for row in rows], dtype=float)\n    x_cols = [np.ones(len(rows), dtype=float)]\n    term_names = ["intercept"]\n    for col in covariate_columns:\n        x_cols.append(np.asarray([float(row[col]) for row in rows], dtype=float))\n        term_names.append(col)\n    X = np.column_stack(x_cols)\n    offset_vector = np.zeros(len(rows), dtype=float)\n    transformed_y = y.copy()\n    if offset_column is not None:\n        raw_offset = np.asarray([max(float(row[offset_column]), 1e-12) for row in rows], dtype=float)\n        if family == "poisson_count_with_log_offset":\n            offset_vector = np.log(raw_offset)\n            transformed_y = np.log(np.maximum(y, 1e-12)) - offset_vector\n        else:\n            x_cols.append(raw_offset)\n            X = np.column_stack(x_cols)\n            term_names.append(offset_column)\n    beta, *_ = np.linalg.lstsq(X, transformed_y, rcond=None)\n    linear = X @ beta\n    if family == "poisson_count_with_log_offset" and offset_column is not None:\n        fitted = np.exp(offset_vector + linear)\n    else:\n        fitted = linear\n    residual = y - fitted\n    sigma = float(np.std(residual, ddof=1)) if len(residual) > 1 else 0.0\n    standardized = residual / sigma if sigma > 0 else residual * 0.0\n    return {\n        "terms": term_names,\n        "coefficients": [float(v) for v in beta.tolist()],\n        "observed": [float(v) for v in y.tolist()],\n        "fitted": [float(v) for v in fitted.tolist()],\n        "residual": [float(v) for v in residual.tolist()],\n        "standardized_residual": [float(v) for v in standardized.tolist()],\n        "rmse": float(math.sqrt(float(np.mean(np.square(residual))))) if len(residual) else None,\n        "mean_residual": float(np.mean(residual)) if len(residual) else None,\n        "sigma": sigma,\n    }\n\n\ndef build_pirs_model_execution_manifest(*, run_dir: str | Path, design_matrix_manifest: str | Path | Mapping[str, Any] | None = None, output_manifest: str | Path | None = None, mutate_output_bundle: bool = True, validate: bool = True) -> dict[str, Any]:\n    root = Path(run_dir)\n    design_manifest_path = Path(design_matrix_manifest) if isinstance(design_matrix_manifest, (str, Path)) else root / DEFAULT_MATRIX_MANIFEST\n    model_manifest_path = Path(output_manifest) if output_manifest is not None else root / DEFAULT_MODEL_MANIFEST\n    manifest = dict(design_matrix_manifest) if isinstance(design_matrix_manifest, Mapping) else _load_json(design_manifest_path)\n    reasons: list[str] = []\n    if manifest.get("status") != "ready":\n        reasons.append(f"design_matrix_manifest_not_ready:{manifest.get(\'status\', \'missing\')}")\n    if manifest.get("matrix_written") is not True:\n        reasons.append("design_matrix_not_written")\n    matrix_path = _matrix_path(root, manifest)\n    if not matrix_path.exists():\n        reasons.append(f"design_matrix_file_missing:{matrix_path}")\n    if reasons:\n        return _blocking_manifest(run_dir=root, model_manifest_path=model_manifest_path, design_matrix_manifest_path=design_manifest_path, reasons=reasons)\n\n    rows = _read_rows(matrix_path)\n    if not rows:\n        return _blocking_manifest(run_dir=root, model_manifest_path=model_manifest_path, design_matrix_manifest_path=design_manifest_path, reasons=["design_matrix_has_no_rows"])\n    response_column, covariate_columns, offset_column = _design_columns(manifest, rows)\n    if response_column not in rows[0]:\n        return _blocking_manifest(run_dir=root, model_manifest_path=model_manifest_path, design_matrix_manifest_path=design_manifest_path, reasons=[f"response_column_missing:{response_column}"])\n    family = str(manifest.get("family") or "gaussian_identity")\n    outcome_field_id = _field_id_by_role(manifest, "outcome") or response_column\n    covariate_field_ids = _covariate_field_ids(manifest)\n    offset_field_id = _field_id_by_role(manifest, "offset")\n    model_basis = {"outcome": outcome_field_id, "covariates": covariate_field_ids, "offset": offset_field_id, "family": family, "matrix_manifest": str(design_manifest_path), "row_count": len(rows)}\n    digest = _hash_payload(model_basis)[:12]\n    model_id = f"pirs_model_{_safe_id(outcome_field_id)}_{digest}"\n    residual_field_id = f"pirs_residual_{_safe_id(outcome_field_id)}_{digest}"\n    fit = _fit_least_squares(rows=rows, response_column=response_column, covariate_columns=covariate_columns, offset_column=offset_column, family=family)\n    coefficients = [{"model_id": model_id, "term": term, "coefficient": coef, "term_index": i, "family": family} for i, (term, coef) in enumerate(zip(fit["terms"], fit["coefficients"], strict=False))]\n    fitted_rows = []\n    residual_rows = []\n    for i, (observed, fitted, residual, standardized) in enumerate(zip(fit["observed"], fit["fitted"], fit["residual"], fit["standardized_residual"], strict=False)):\n        row_id = rows[i].get("row_id", i)\n        fitted_rows.append({"model_id": model_id, "row_id": row_id, "observed": observed, "fitted": fitted, "residual": residual, "standardized_residual": standardized})\n        residual_rows.append({"field_id": residual_field_id, "model_id": model_id, "row_id": row_id, "residual": residual, "standardized_residual": standardized})\n    coefficients_path = root / DEFAULT_COEFFICIENTS\n    fitted_values_path = root / DEFAULT_FITTED_VALUES\n    residual_values_path = root / DEFAULT_RESIDUAL_VALUES\n    _write_rows(coefficients_path, coefficients)\n    _write_rows(fitted_values_path, fitted_rows)\n    _write_rows(residual_values_path, residual_rows)\n\n    payload = {\n        "schema_version": "1.0",\n        "slice": "17B",\n        "artifact": "pirs_model_execution_manifest",\n        "status": "fitted",\n        "model_fit_state": "fitted",\n        "residual_state": "materialized",\n        "hsic_state": "blocked",\n        "run_dir": str(root),\n        "manifest_path": str(model_manifest_path),\n        "source_design_matrix_manifest": str(design_manifest_path),\n        "design_matrix_path": str(matrix_path),\n        "model_id": model_id,\n        "residual_field_id": residual_field_id,\n        "outcome_field_id": outcome_field_id,\n        "covariate_field_ids": covariate_field_ids,\n        "offset_field_id": offset_field_id,\n        "family": family,\n        "row_count": len(rows),\n        "coefficient_count": len(coefficients),\n        "coefficients_path": str(coefficients_path),\n        "fitted_values_path": str(fitted_values_path),\n        "residual_values_path": str(residual_values_path),\n        "diagnostics": {"rmse": fit["rmse"], "mean_residual": fit["mean_residual"], "sigma": fit["sigma"], "residual_mode": manifest.get("residual_mode"), "fold_scheme": manifest.get("fold_scheme")},\n        "blocking_reasons": [],\n        "mutated_output_bundle": False,\n    }\n    if mutate_output_bundle:\n        _mutate_output_bundle_with_model_result(root, payload, residual_vector=fit["residual"])\n        payload["mutated_output_bundle"] = True\n        if validate:\n            from pegasus.output.validate import validate_output_bundle\n\n            validation = validate_output_bundle(run_dir=str(root))\n            payload["output_validation"] = {"ok": validation.ok, "errors": validation.errors, "warnings": validation.warnings}\n            if not validation.ok:\n                payload["status"] = "invalid_output_bundle"\n                payload["model_fit_state"] = "fitted_but_invalid_output_bundle"\n    summary = pirs_model_execution_summary(payload, manifest_path=model_manifest_path)\n    payload["summary"] = summary\n    _write_json(model_manifest_path, payload)\n    return payload\n\n\ndef _mutate_output_bundle_with_model_result(root: Path, payload: Mapping[str, Any], *, residual_vector: Sequence[float]) -> None:\n    residual_field_id = str(payload["residual_field_id"])\n    model_id = str(payload["model_id"])\n    outcome = str(payload.get("outcome_field_id") or "")\n    covariates = list(payload.get("covariate_field_ids") or [])\n    support = {"row_count": payload.get("row_count"), "source_design_matrix_manifest": payload.get("source_design_matrix_manifest")}\n    axes = {"support_index": "design_matrix_row_id"}\n    warning_id = f"warning_{residual_field_id}"\n    residual_field = {\n        "field_id": residual_field_id,\n        "name": f"PIRS model residual for {outcome}",\n        "kind": "model_residual",\n        "carrier": "model_residual",\n        "unit": "residual",\n        "aggregation": "non_aggregable",\n        "role": _compact(["model_residual", "pirs", "diagnostic_residual"]),\n        "source": _compact(["PIRS", "model_execution"]),\n        "support_json": _compact(support),\n        "axes_json": _compact(axes),\n        "operator": "pirs_model_execution_residualization",\n        "provenance": _compact(["model_derived"]),\n        "state": "warning",\n        "dashboard_safe": "False",\n        "warnings": _compact([RESIDUAL_WARNING]),\n        "lineage_hash": _hash_payload({"model_id": model_id, "residual_field_id": residual_field_id, "support": support}),\n        "registry_hash": "slice17b_pirs_model_execution_v1",\n        "materialization_state": "materialized",\n        "path": str(root / DEFAULT_RESIDUAL_VALUES),\n    }\n    q_row = {\n        "field_id": residual_field_id,\n        "n_events": None,\n        "n_denom": None,\n        "n_eff": float(len(residual_vector)),\n        "cov_S": 1.0,\n        "cov_T": 1.0,\n        "missingness": 0.0,\n        "zero_inflation": 0.0,\n        "denom_fragility": 0.0,\n        "cv": None,\n        "moran_i": None,\n        "temporal_roughness": None,\n        "spatial_entropy": None,\n        "provenance_risk": 0.4,\n        "state": "warning",\n        "dashboard_safe": "False",\n        "warnings": _compact([RESIDUAL_WARNING]),\n        "computed_at": _now(),\n        "q_schema_version": "1.0",\n        "values_json": _compact([float(v) for v in residual_vector]),\n        "value_vector_json": _compact([float(v) for v in residual_vector]),\n    }\n    vd_row = {\n        "field_id": residual_field_id,\n        "display_name": residual_field["name"],\n        "technical_name": residual_field_id,\n        "definition": "Model-derived PIRS residual vector produced from a validated design matrix.",\n        "estimand_label": "PIRS model residual",\n        "source_systems": residual_field["source"],\n        "carrier": residual_field["carrier"],\n        "unit": residual_field["unit"],\n        "support_description": residual_field["support_json"],\n        "axis_description": residual_field["axes_json"],\n        "provenance_description": residual_field["provenance"],\n        "state": residual_field["state"],\n        "dashboard_safe": residual_field["dashboard_safe"],\n        "interpretation_warning": RESIDUAL_WARNING,\n    }\n    model_assoc = {"id": model_id, "model_id": model_id, "status": payload.get("status"), "family": payload.get("family"), "outcome_field_id": outcome, "covariate_field_id": _compact(covariates), "covariate_field_ids": _compact(covariates), "offset_field_id": payload.get("offset_field_id"), "residual_field_id": residual_field_id, "diagnostics_json": _compact(payload.get("diagnostics", {})), "created_at": _now()}\n    residual_assoc = {"id": residual_field_id, "residual_association_id": residual_field_id, "residual_field_id": residual_field_id, "model_id": model_id, "parent_model_id": model_id, "outcome_field_id": outcome, "residual_type": "raw_response_residual", "status": "materialized", "created_at": _now()}\n    warning = {"warning_id": warning_id, "field_id": residual_field_id, "source": "PIRS", "severity": "warning", "code": RESIDUAL_WARNING, "message": "PIRS residual is a model-derived diagnostic field, not a raw epidemiological observation.", "inherited_from": "[]", "created_at": _now()}\n    _append_unique_rows_like(root / "V_fields.parquet", [residual_field], id_column="field_id")\n    _append_unique_rows_like(root / "Q_tensor.parquet", [q_row], id_column="field_id")\n    _append_unique_rows_like(root / "VariableDictionary.parquet", [vd_row], id_column="field_id")\n    _append_unique_rows_like(root / "ModelAssociations.parquet", [model_assoc], id_column="id")\n    _append_unique_rows_like(root / "ResidualAssociations.parquet", [residual_assoc], id_column="id")\n    _append_unique_rows_like(root / "Warnings.parquet", [warning], id_column="warning_id")\n\n\ndef pirs_model_execution_summary(payload: Mapping[str, Any], *, manifest_path: str | Path | None = None) -> dict[str, Any]:\n    return {\n        "schema_version": "1.0",\n        "slice": "17B",\n        "gate": MODEL_GATE_KEY,\n        "status": payload.get("status"),\n        "model_fit_state": payload.get("model_fit_state"),\n        "residual_state": payload.get("residual_state"),\n        "hsic_state": payload.get("hsic_state", "blocked"),\n        "model_id": payload.get("model_id"),\n        "residual_field_id": payload.get("residual_field_id"),\n        "row_count": payload.get("row_count", 0),\n        "coefficient_count": payload.get("coefficient_count", 0),\n        "mutated_output_bundle": bool(payload.get("mutated_output_bundle")),\n        "blocking_reason_count": len(payload.get("blocking_reasons") or []),\n        "manifest_path": str(manifest_path) if manifest_path is not None else payload.get("manifest_path"),\n        "output_validation": payload.get("output_validation"),\n    }\n\n\ndef attach_pirs_model_execution_gate_to_run(*, run_dir: str | Path, summary: Mapping[str, Any]) -> None:\n    root = Path(run_dir)\n    for rel in JSON_ATTACH_TARGETS:\n        path = root / rel\n        doc = _load_json(path)\n        doc[MODEL_GATE_KEY] = dict(summary)\n        if rel == "ReproducibilityManifest.json":\n            pirs = doc.setdefault("pirs", {})\n            if isinstance(pirs, dict):\n                pirs["model_execution"] = dict(summary)\n            telemetry = doc.setdefault("telemetry", {})\n            if isinstance(telemetry, dict):\n                stage_status = telemetry.setdefault("stage_status", {})\n                if isinstance(stage_status, dict):\n                    stage_status["pirs_model"] = "success" if summary.get("status") == "fitted" else "blocked"\n                    stage_status["pirs_hsic"] = "blocked"\n        _write_json(path, doc)\n\n\ndef execute_pirs_model_from_design_matrix(*, run_dir: str | Path, design_matrix_manifest: str | Path | Mapping[str, Any] | None = None, output_manifest: str | Path | None = None, mutate_output_bundle: bool = True, validate: bool = True, attach: bool = True) -> dict[str, Any]:\n    payload = build_pirs_model_execution_manifest(run_dir=run_dir, design_matrix_manifest=design_matrix_manifest, output_manifest=output_manifest, mutate_output_bundle=mutate_output_bundle, validate=validate)\n    summary = pirs_model_execution_summary(payload, manifest_path=payload.get("manifest_path"))\n    payload["summary"] = summary\n    _write_json(Path(str(payload["manifest_path"])), payload)\n    if attach:\n        attach_pirs_model_execution_gate_to_run(run_dir=run_dir, summary=summary)\n    return {"manifest_path": payload["manifest_path"], MODEL_GATE_KEY: summary, "model_execution": payload}\n\n\ndef inspect_pirs_model_execution_manifest(manifest: str | Path) -> dict[str, Any]:\n    payload = _load_json(Path(manifest))\n    if not payload:\n        raise FileNotFoundError(f"missing or invalid PIRS model execution manifest: {manifest}")\n    summary = payload.get("summary")\n    if isinstance(summary, Mapping):\n        return dict(summary)\n    return pirs_model_execution_summary(payload, manifest_path=manifest)\n'
WORKFLOW = '\n"""Workflow wrappers for Slice 17B PIRS model execution."""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import Any\n\nfrom pegasus.pirs.model_execution import execute_pirs_model_from_design_matrix, inspect_pirs_model_execution_manifest\n\n\ndef run_execute_pirs_model(*, run_dir: str | Path, design_matrix_manifest: str | Path | dict[str, Any] | None = None, output_manifest: str | Path | None = None, mutate_output_bundle: bool = True, validate: bool = True, attach: bool = True) -> dict[str, Any]:\n    return execute_pirs_model_from_design_matrix(run_dir=run_dir, design_matrix_manifest=design_matrix_manifest, output_manifest=output_manifest, mutate_output_bundle=mutate_output_bundle, validate=validate, attach=attach)\n\n\n__all__ = ["inspect_pirs_model_execution_manifest", "run_execute_pirs_model"]\n'
CLI_BLOCK = '\n\n# ---- Slice 17B PIRS model execution CLI boundary ----\n@pirs_app.command("execute-model")\ndef pirs_execute_model(\n    run_dir: Path = typer.Option(..., "--run-dir"),\n    design_matrix_manifest: Path | None = typer.Option(None, "--design-matrix-manifest"),\n    output_manifest: Path | None = typer.Option(None, "--output-manifest"),\n    mutate_output_bundle: bool = typer.Option(True, "--mutate-output-bundle/--no-mutate-output-bundle"),\n    validate: bool = typer.Option(True, "--validate/--no-validate"),\n    attach: bool = typer.Option(True, "--attach/--no-attach"),\n) -> None:\n    """Execute PIRS model fitting from a ready design matrix and materialize residual artifacts."""\n    from pegasus.workflows.pirs_execute import run_execute_pirs_model\n\n    _pirs_cli_print(run_execute_pirs_model(run_dir=run_dir, design_matrix_manifest=design_matrix_manifest, output_manifest=output_manifest, mutate_output_bundle=mutate_output_bundle, validate=validate, attach=attach))\n\n\n@pirs_app.command("inspect-model-execution")\ndef pirs_inspect_model_execution(\n    manifest: Path = typer.Option(..., "--manifest"),\n) -> None:\n    """Read an existing PIRS model-execution manifest without mutating a run."""\n    from pegasus.pirs.model_execution import inspect_pirs_model_execution_manifest\n\n    _pirs_cli_print(inspect_pirs_model_execution_manifest(manifest))\n# ---- End Slice 17B PIRS model execution CLI boundary ----\n'
UNIT_TEST = '\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\n\nfrom pegasus.pirs.model_execution import build_pirs_model_execution_manifest, inspect_pirs_model_execution_manifest\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef test_slice17b_blocks_when_design_matrix_manifest_is_not_ready(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run"\n    (run_dir / "Tables").mkdir(parents=True)\n    _write_json(run_dir / "Tables" / "pirs_design_matrix_manifest.json", {"status": "blocked", "matrix_written": False})\n    payload = build_pirs_model_execution_manifest(run_dir=run_dir, mutate_output_bundle=False)\n    assert payload["status"] == "blocked"\n    assert payload["model_fit_state"] == "blocked"\n    assert payload["mutated_output_bundle"] is False\n    assert any(str(reason).startswith("design_matrix_manifest_not_ready") for reason in payload["blocking_reasons"])\n\n\ndef test_slice17b_fits_design_matrix_and_writes_model_artifacts_without_bundle_mutation(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run"\n    (run_dir / "Tables").mkdir(parents=True)\n    matrix = run_dir / "Tables" / "pirs_design_matrix.parquet"\n    pq.write_table(pa.Table.from_pylist([\n        {"row_id": 0, "intercept": 1.0, "response": 1.0, "covariate_001": 1.0},\n        {"row_id": 1, "intercept": 1.0, "response": 2.0, "covariate_001": 2.0},\n        {"row_id": 2, "intercept": 1.0, "response": 3.0, "covariate_001": 3.0},\n    ]), matrix)\n    _write_json(run_dir / "Tables" / "pirs_design_matrix_manifest.json", {"status": "ready", "matrix_written": True, "matrix_path": str(matrix), "family": "gaussian_identity", "field_specs": [{"field_id": "field:y", "role": "outcome", "column": "response"}, {"field_id": "field:x", "role": "covariate", "column": "covariate_001"}]})\n    payload = build_pirs_model_execution_manifest(run_dir=run_dir, mutate_output_bundle=False)\n    assert payload["status"] == "fitted"\n    assert payload["model_fit_state"] == "fitted"\n    assert payload["residual_state"] == "materialized"\n    assert payload["coefficient_count"] == 2\n    assert Path(payload["coefficients_path"]).exists()\n    assert Path(payload["residual_values_path"]).exists()\n    inspected = inspect_pirs_model_execution_manifest(run_dir / "Tables" / "pirs_model_execution_manifest.json")\n    assert inspected["status"] == "fitted"\n'
INTEGRATION_TEST = '\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\nfrom typer.testing import CliRunner\n\nfrom pegasus.cli import app\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.workflows.pirs_execute import run_execute_pirs_model\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef _ready_run(run_dir: Path) -> None:\n    create_empty_output_bundle(run_dir)\n    matrix = run_dir / "Tables" / "pirs_design_matrix.parquet"\n    pq.write_table(pa.Table.from_pylist([\n        {"row_id": 0, "intercept": 1.0, "response": 10.0, "covariate_001": 1.0},\n        {"row_id": 1, "intercept": 1.0, "response": 12.0, "covariate_001": 2.0},\n        {"row_id": 2, "intercept": 1.0, "response": 14.0, "covariate_001": 3.0},\n        {"row_id": 3, "intercept": 1.0, "response": 16.0, "covariate_001": 4.0},\n    ]), matrix)\n    _write_json(run_dir / "Tables" / "pirs_design_matrix_manifest.json", {"status": "ready", "matrix_written": True, "matrix_path": str(matrix), "family": "gaussian_identity", "residual_mode": "in_sample", "fold_scheme": "none_in_sample_fast_budget", "field_specs": [{"field_id": "deaths", "role": "outcome", "column": "response"}, {"field_id": "capacity", "role": "covariate", "column": "covariate_001"}]})\n\n\ndef test_slice17b_executes_model_mutates_bundle_and_validates(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run"\n    _ready_run(run_dir)\n    result = run_execute_pirs_model(run_dir=run_dir)\n    gate = result["pirs_model_execution_gate"]\n    assert gate["status"] == "fitted"\n    assert gate["mutated_output_bundle"] is True\n    assert gate["residual_field_id"]\n    validation = validate_output_bundle(run_dir=str(run_dir))\n    assert validation.ok, validation.errors\n    v_rows = pq.read_table(run_dir / "V_fields.parquet").to_pylist()\n    assert any(row["field_id"] == gate["residual_field_id"] and row["kind"] == "model_residual" for row in v_rows)\n    model_rows = pq.read_table(run_dir / "ModelAssociations.parquet").to_pylist()\n    residual_rows = pq.read_table(run_dir / "ResidualAssociations.parquet").to_pylist()\n    assert any(row.get("id") == gate["model_id"] for row in model_rows)\n    assert any(row.get("id") == gate["residual_field_id"] for row in residual_rows)\n    manifest = json.loads((run_dir / "ReproducibilityManifest.json").read_text(encoding="utf-8"))\n    assert manifest["pirs_model_execution_gate"]["status"] == "fitted"\n\n\ndef test_slice17b_cli_executes_and_inspects_model_manifest(tmp_path: Path) -> None:\n    run_dir = tmp_path / "run_cli"\n    _ready_run(run_dir)\n    runner = CliRunner()\n    result = runner.invoke(app, ["pirs", "execute-model", "--run-dir", str(run_dir)])\n    assert result.exit_code == 0, result.output\n    assert \'"status": "fitted"\' in result.output\n    manifest = run_dir / "Tables" / "pirs_model_execution_manifest.json"\n    assert manifest.exists()\n    result = runner.invoke(app, ["pirs", "inspect-model-execution", "--manifest", str(manifest)])\n    assert result.exit_code == 0, result.output\n    assert \'"model_fit_state": "fitted"\' in result.output\n'
AUDIT = '\nfrom __future__ import annotations\n\nimport ast\nimport json\nimport tempfile\nfrom pathlib import Path\n\nimport pyarrow as pa\nimport pyarrow.parquet as pq\n\nfrom pegasus.output.bundle import create_empty_output_bundle\nfrom pegasus.output.validate import validate_output_bundle\nfrom pegasus.workflows.pirs_execute import run_execute_pirs_model\n\n\ndef _count_defs(path: Path, name: str) -> int:\n    tree = ast.parse(path.read_text(encoding="utf-8"))\n    return sum(1 for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == name)\n\n\ndef _write_json(path: Path, payload: dict) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2), encoding="utf-8")\n\n\ndef main() -> int:\n    errors: list[str] = []\n    if _count_defs(Path("src/pegasus/workflows/compile.py"), "run_compile") != 1:\n        errors.append("compile.py public run_compile count changed")\n    if _count_defs(Path("src/pegasus/pirs/model_execution.py"), "build_pirs_model_execution_manifest") != 1:\n        errors.append("model execution builder API missing")\n    cli = Path("src/pegasus/cli.py").read_text(encoding="utf-8")\n    if \'@pirs_app.command("execute-model")\' not in cli:\n        errors.append("CLI execute-model command missing")\n    with tempfile.TemporaryDirectory() as tmp:\n        run_dir = Path(tmp) / "run"\n        create_empty_output_bundle(run_dir)\n        matrix = run_dir / "Tables" / "pirs_design_matrix.parquet"\n        pq.write_table(pa.Table.from_pylist([\n            {"row_id": 0, "intercept": 1.0, "response": 1.0, "covariate_001": 0.0},\n            {"row_id": 1, "intercept": 1.0, "response": 2.0, "covariate_001": 1.0},\n            {"row_id": 2, "intercept": 1.0, "response": 3.0, "covariate_001": 2.0},\n        ]), matrix)\n        _write_json(run_dir / "Tables" / "pirs_design_matrix_manifest.json", {"status": "ready", "matrix_written": True, "matrix_path": str(matrix), "family": "gaussian_identity", "field_specs": [{"field_id": "outcome", "role": "outcome", "column": "response"}, {"field_id": "cov", "role": "covariate", "column": "covariate_001"}]})\n        result = run_execute_pirs_model(run_dir=run_dir)\n        gate = result.get("pirs_model_execution_gate", {})\n        if gate.get("status") != "fitted":\n            errors.append("synthetic run did not fit")\n        validation = validate_output_bundle(run_dir=str(run_dir))\n        if not validation.ok:\n            errors.append("output bundle invalid after PIRS model execution: " + "; ".join(validation.errors))\n        for rel in ("Tables/pirs_model_execution_manifest.json", "Tables/pirs_model_coefficients.parquet", "Tables/pirs_fitted_values.parquet", "Tables/pirs_residual_values.parquet"):\n            if not (run_dir / rel).exists():\n                errors.append(f"missing model execution artifact: {rel}")\n    print(json.dumps({"ok": not errors, "errors": errors}, ensure_ascii=False, sort_keys=True, indent=2))\n    if errors:\n        return 1\n    print("AUDIT PASSED: Slice 17B PIRS model execution and residual materialization")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


def fail(message: str) -> None:
    raise SystemExit(f"[slice17b] {message}")


def read(path: str) -> str:
    p = ROOT / path
    if not p.exists():
        fail(f"required file missing: {path}")
    return p.read_text(encoding="utf-8")


def write(path: str, text: str) -> None:
    if path.startswith(FORBIDDEN_PREFIXES):
        fail(f"refusing to write forbidden path: {path}")
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text.rstrip() + "\n", encoding="utf-8")


def top_level_function_count(text: str, name: str) -> int:
    tree = ast.parse(text)
    return sum(1 for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == name)


def preflight() -> None:
    required = (
        "src/pegasus/pirs/design_matrix.py",
        "src/pegasus/workflows/pirs_matrix.py",
        "src/pegasus/workflows/pirs_pipeline.py",
        "src/pegasus/cli.py",
    )
    for path in required:
        if not (ROOT / path).exists():
            fail(f"required preflight file missing: {path}")
    compile_text = read("src/pegasus/workflows/compile.py")
    if top_level_function_count(compile_text, "run_compile") != 1:
        fail("compile.py must still contain exactly one public run_compile")
    if top_level_function_count(compile_text, "_run_compile_impl") != 1:
        fail("compile.py must still contain exactly one private _run_compile_impl")
    if "build_pirs_design_matrix_manifest" not in read("src/pegasus/pirs/design_matrix.py"):
        fail("Slice 17A design-matrix boundary not detected")
    cli = read("src/pegasus/cli.py")
    if "pirs_app = typer.Typer" not in cli or 'app.add_typer(pirs_app, name="pirs")' not in cli:
        fail("cli.py does not expose pirs_app")


def strip_existing_block(text: str) -> str:
    start = text.find(MARKER_START)
    if start == -1:
        return text
    end = text.find(MARKER_END, start)
    if end == -1:
        return text[:start].rstrip() + "\n"
    end_line = text.find("\n", end)
    if end_line == -1:
        return text[:start].rstrip() + "\n"
    return (text[:start] + text[end_line + 1:]).rstrip() + "\n"


def patch_cli() -> None:
    path = "src/pegasus/cli.py"
    text = strip_existing_block(read(path))
    if "def _pirs_cli_print" not in text:
        fail("cli.py missing Slice 16E _pirs_cli_print helper")
    if "pirs_app = typer.Typer" not in text:
        fail("cli.py missing pirs_app")
    text = text.rstrip() + CLI_BLOCK
    for token in ('@pirs_app.command("execute-model")', '@pirs_app.command("inspect-model-execution")'):
        if token not in text:
            fail(f"cli patch missing token: {token}")
    write(path, text)


def write_files() -> None:
    write("src/pegasus/pirs/model_execution.py", MODEL_EXECUTION)
    write("src/pegasus/workflows/pirs_execute.py", WORKFLOW)
    patch_cli()
    write("tests/unit/test_slice17b_pirs_model_execution.py", UNIT_TEST)
    write("tests/integration/test_slice17b_pirs_model_execution_integration.py", INTEGRATION_TEST)
    write("scripts/dev/audits/audit_slice17b_pirs_model_execution.py", AUDIT)


def self_validate() -> None:
    for path in TOUCH_LIST:
        py_compile.compile(str(ROOT / path), doraise=True)
    src = str(ROOT / "src")
    if src not in sys.path:
        sys.path.insert(0, src)
    from pegasus.pirs.model_execution import build_pirs_model_execution_manifest
    from pegasus.workflows.pirs_execute import run_execute_pirs_model
    if not callable(build_pirs_model_execution_manifest) or not callable(run_execute_pirs_model):
        fail("post-validate: PIRS model execution APIs not callable")


def main() -> None:
    preflight()
    write_files()
    self_validate()
    print("Slice 17B updater applied: PIRS model execution, residual materialization, and CLI added.")
    print("Touched files:")
    for path in TOUCH_LIST:
        print(f"  - {path}")


if __name__ == "__main__":
    main()
